CREATE INDEX IF NOT EXISTS idx_projects_published_featured ON projects(published,featured,sort_order);
CREATE INDEX IF NOT EXISTS idx_messages_status_created ON messages(status,created_at DESC);
CREATE TABLE IF NOT EXISTS experiences (id BIGSERIAL PRIMARY KEY,role VARCHAR(180) NOT NULL,company VARCHAR(180),location VARCHAR(180),start_date DATE,end_date DATE,current_role BOOLEAN NOT NULL DEFAULT FALSE,summary TEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS education (id BIGSERIAL PRIMARY KEY,institution VARCHAR(180) NOT NULL,qualification VARCHAR(180) NOT NULL,start_date DATE,end_date DATE,summary TEXT,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS blog_posts (id BIGSERIAL PRIMARY KEY,title VARCHAR(220) NOT NULL,slug VARCHAR(220) UNIQUE NOT NULL,excerpt TEXT,content TEXT NOT NULL,published BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS media (id BIGSERIAL PRIMARY KEY,filename VARCHAR(255) NOT NULL,storage_path TEXT NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes BIGINT NOT NULL,alt_text VARCHAR(255),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY,admin_id BIGINT REFERENCES admins(id) ON DELETE SET NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(120),entity_id BIGINT,metadata JSONB,ip_address INET,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
